<?php declare(strict_types=1);require_once __DIR__.'/auth.php';$u=portal_require();$q=$db->prepare('SELECT client_id FROM client_portal_users WHERE id=?');$q->execute([$u['id']]);$client=(int)$q->fetchColumn();$q=$db->prepare("SELECT id,project_id,name,description,due_date,status FROM project_milestones WHERE project_id IN (SELECT id FROM client_projects WHERE client_id=?) ORDER BY due_date");$q->execute([$client]);$rows=$q->fetchAll();?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Approvals</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body><main class="container py-4"><a href="index.php">← Dashboard</a><h1 class="h3 mt-3">Approvals & Sign-offs</h1><div class="alert alert-info">Pending milestone approvals can be reviewed here. Approval actions can be connected to your existing approval workflow.</div><table class="table"><thead><tr><th>Milestone</th><th>Project</th><th>Due</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=htmlspecialchars($r['name'])?></td><td><?=htmlspecialchars((string)$r['project_id'])?></td><td><?=htmlspecialchars($r['due_date']??'')?></td><td><?=htmlspecialchars($r['status'])?></td></tr><?php endforeach;?></tbody></table></main></body></html>